call_args.script:
cd /app && cat > /tmp/verify_signatures.go << 'EOF'
package main
import (
	"context"
	"fmt"
	"reflect"
	"github.com/cloudwego/kitex/pkg/endpoint/cep"
	"github.com/cloudwego/kitex/pkg/endpoint/sep"
	"github.com/cloudwego/kitex/pkg/streaming"
)

func main() {
	// Verify cep.StreamEndpoint signature (factory pattern - returns ClientStream)
	var cepFunc cep.StreamEndpoint = func(ctx context.Context) (streaming.ClientStream, error) {
		return nil, nil
	}
	cepType := reflect.TypeOf(cepFunc)
	fmt.Println("cep.StreamEndpoint signature:")
	fmt.Printf("  Params: %d (ctx)\n", cepType.NumIn())
	fmt.Printf("  Returns: %d (ClientStream, error)\n", cepType.NumOut())
	fmt.Printf("  ✅ Factory pattern - RETURNS ClientStream\n\n")

	// Verify sep.StreamEndpoint signature (handler pattern - takes ServerStream)
	var sepFunc sep.StreamEndpoint = func(ctx context.Context, st streaming.ServerStream) error {
		return nil
	}
	sepType := reflect.TypeOf(sepFunc)
	fmt.Println("sep.StreamEndpoint signature:")
	fmt.Printf("  Params: %d (ctx, ServerStream)\n", sepType.NumIn())
	fmt.Printf("  Returns: %d (error)\n", sepType.NumOut())
	fmt.Printf("  ✅ Handler pattern - TAKES ServerStream parameter\n")
}
EOF
go run /tmp/verify_signatures.go 2>&1

